; emitsn.s -- generated by tools/fwtask/gen_blobs.py (phase r38): round 38 (N3c): emitsb's entry 0 without the emitpds (cmd 1): M1, X0, then M4, the echo and state done in entry 0, and the closed task
; Written from doc/specs/usse_isa.md and the records E475/E476 (pclink, lapc), E480 (wdf with
; nothing outstanding), E512 (stad then ldad), E146/E155 (the event task, pa0 to pa2); it is run
; as an EDM task from the page the kernel maps at heap + 0x20000 (index 0x4000). Rules: r0 to r31
; only, no sa write except state.s, no emit, no lock, every store the same value from every lane.

@entry 0
        mov r1, #0xdeadbeef                 ; @patch res+0
        ldad.bypassl1 r2, [r1,+#1], drc0   ; cmd
        wdf drc0
        and.testtanz.chan0 !c0, p0, r2, r2  ; p0 = cmd != 0
        p0 br @work
tail:
        mov r30, #0xdeadbeef                ; @patch cont0
        mov pclink, r30
        lapc
work:
        xor.testtaz.chan0 !c0, p1, r2, #1
        p1 br @c1
        br @tail
c1:
        mov r9, #0xdeadbeef                ; @patch res+272
        mov r7, #0x5a5a3301
        ldad.bypassl1 r5, [r1,+#3], drc0   ; the run id
        wdf drc0
        stad [r9,+#0], r7
        stad [r9,+#1], r5
        mov r4, #0x00000000
        stad [r1,+#1], r4                  ; cmd = 0: one emit per command
        idf drc0, bif
        wdf drc0
        mov r7, #0x5a5a3303
        stad [r9,+#2], r7
        idf drc0, bif
        wdf drc0
        mov r9, #0xdeadbeef                ; @patch res+320
        mov r7, #0x5a5a3302
        ldad.bypassl1 r5, [r1,+#3], drc0   ; the run id
        wdf drc0
        stad [r9,+#0], r7
        stad [r9,+#1], r5
        stad [r1,+#5], r5
        mov r3, #0x00000002
        idf drc0, bif
        wdf drc0
        stad [r1,+#2], r3                ; state = done
        br @tail
